  "_page": 215,
  "_book_file": "TD_McDonald_and_Avery's_Dentistry_for_the_Child_and_Adolescent",
  "_context": "nt molars, and lingual pits on the maxillary permanent lateral incisors are vulnerable areas in which the process of dental caries may proceed rapidly.41 Molar incisor hypomineralization (MIH) is a common developmental enamel defect characterized by asymmetrical distribution of hypomineralized demarcated opacities in first permanent molars and incisors. It is now generally accepted that it is a multifactorial genetic condition that modulates the individual’s response to the different environmental insults. Hypomineralization is a defect of the quality of enamel. Severe hypomineralized enamel is not resistant to mastication forces and breakdowns easily upon eruption favoring aggressive caries"
